import sys,sysconfig,json,hashlib,importlib.util
from pathlib import Path
origins={}
roots=[]
for name in ('openmm','numpy','matplotlib','psi4'):
 spec=importlib.util.find_spec(name)
 if spec is not None and spec.origin:
  origin=Path(spec.origin).resolve();origins[name]=str(origin);roots.append(origin.parent)
  if name=='openmm':roots.append(origin.parent.parent/'OpenMM.libs')
  if name=='numpy':roots.append(origin.parent.parent/'numpy.libs')
files={p.resolve() for root in roots if root.is_dir() for p in root.rglob('*') if p.is_file() and ('.so' in p.name or p.suffix=='.dylib')}
files|={p.resolve() for p in (Path(sys.prefix)/'lib').glob('*OpenMM*.so*') if p.is_file()}
print(json.dumps({'executable':sys.executable,'resolved_module_origins':origins,'native_libraries':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(files)}}))

